def cZeroSum_insertFun {I J : Type u} {E : J → Type v}
    [∀ j, Zero (E j)] (e : I → J) (x : ∀ i, E (e i)) (j : J) : E j :=
  if h : ∃ i, e i = j then h.choose_spec ▸ x h.choose else 0

