@[simp] theorem cZeroSum_insertFun_apply {I J : Type u} {E : J → Type v}
    [∀ j, Zero (E j)] (e : I → J) (he : Function.Injective e)
    (x : ∀ i, E (e i)) (i : I) : cZeroSum_insertFun e x (e i) = x i
